ort_cod_orders co left join cod_reports cr on co.awb = cr.awb and co.awb != \'\' left join courier_mapping c on c.clean_courier = upper(trim(co.courier_partner)) ) select * except (collectible_whole, paid_whole), case when cod_amount_paid is not null and abs(collectible_whole - paid_whole) <= 1 then \'Payment Received - Correct\' when cod_amount_paid is not null and abs(collectible_whole - paid_whole) > 1 then \'Payment Received - Incorrect\' when delivered_date is not null and date_diff(current_date(), date(delivered_date), day) >= 7 then \'Payment Pending\' when delivered_date is not null and date_diff(current_date(), date(delivered_date), day) < 7 then \'Delivered (< 7 Days)\' else \'Not Delivered\' end as payment_status, case when cod_amount_paid is not null and abs(collectible_whole - paid_whole) > 1 then collectible_whole - paid_whole else 0 end as claim_amount from base ;",
